question.answer:
def scaled(readings: list[int]) -> list[int]:
    return [r * 10 for r in readings]


def in_range(readings: list[int]) -> list[int]:
    return [r for r in readings if 0 <= r <= 100]


def floored(readings: list[int]) -> list[int]:
    return [0 if r < 0 else r for r in readings]


def leak_check(readings: list[int]) -> str:
    squares = [n * n for n in readings]
    try:
        n
    except NameError as problem:
        return f"{squares} and n is gone: {problem}"
    return f"{squares} and n leaked"

