question.answer:
def index_of(names: list[str]) -> dict[str, int]:
    return {names[i]: i for i in range(len(names))}


def distinct_units(records: list[dict[str, str]]) -> set[str]:
    return {record["unit"] for record in records}


def by_id(records: list[dict[str, str]]) -> dict[str, dict[str, str]]:
    return {record["id"]: record for record in records}


def invert(mapping: dict[str, str]) -> dict[str, str]:
    return {name: code for code, name in mapping.items()}


def group_by_value(mapping: dict[str, str]) -> dict[str, list[str]]:
    return {name: [code for code, other in mapping.items() if other == name] for name in mapping.values()}

