question.answer:
def numbered(lines: list[str]) -> list[str]:
    return [f"{position}: {line}" for position, line in enumerate(lines, start=1)]


def pair(channels: list[str], readings: list[int]) -> dict[str, int]:
    return {channel: reading for channel, reading in zip(channels, readings, strict=True)}


def flatten(rows: list[list[int]]) -> list[int]:
    return [value for row in rows for value in row]


def transpose(rows: list[list[int]]) -> list[list[int]]:
    return [list(column) for column in zip(*rows, strict=True)]
